CREATE TABLE asset_components(id TEXT PRIMARY KEY,asset_id TEXT NOT NULL REFERENCES assets(id),name TEXT NOT NULL,position TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,UNIQUE(asset_id,name));
CREATE TABLE measurement_points(id TEXT PRIMARY KEY,asset_id TEXT NOT NULL REFERENCES assets(id),component_id TEXT NOT NULL REFERENCES asset_components(id),code TEXT NOT NULL,name TEXT NOT NULL,position TEXT NOT NULL,operating_condition TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,UNIQUE(asset_id,code));
CREATE TABLE sensor_channels(id TEXT PRIMARY KEY,point_id TEXT NOT NULL REFERENCES measurement_points(id),source TEXT NOT NULL,channel INTEGER NOT NULL CHECK(channel BETWEEN 1 AND 64),unit TEXT NOT NULL DEFAULT 'FS',serial_number TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX active_sensor_binding ON sensor_channels(source,channel) WHERE active=1;
CREATE TABLE calibrations(id TEXT PRIMARY KEY,channel_id TEXT NOT NULL REFERENCES sensor_channels(id),gain REAL NOT NULL CHECK(gain>0),offset REAL NOT NULL DEFAULT 0,unit TEXT NOT NULL,valid_from TEXT NOT NULL,valid_until TEXT NOT NULL,reference TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE health_baselines(id TEXT PRIMARY KEY,point_id TEXT NOT NULL REFERENCES measurement_points(id),metric TEXT NOT NULL,minimum REAL,maximum REAL,unit TEXT NOT NULL,operating_condition TEXT NOT NULL,reference TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,CHECK(minimum IS NOT NULL OR maximum IS NOT NULL),CHECK(minimum IS NULL OR maximum IS NULL OR minimum<=maximum));
CREATE TABLE recurring_plans(id TEXT PRIMARY KEY,name TEXT NOT NULL,asset_id TEXT NOT NULL REFERENCES assets(id),point_id TEXT REFERENCES measurement_points(id),assignee_id TEXT NOT NULL REFERENCES users(id),period_days INTEGER NOT NULL CHECK(period_days BETWEEN 1 AND 3650),next_due TEXT NOT NULL,template_snapshot TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE task_settings(task_id TEXT PRIMARY KEY REFERENCES inspection_tasks(id),point_id TEXT REFERENCES measurement_points(id),template_snapshot TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'temporary',plan_id TEXT REFERENCES recurring_plans(id),occurrence TEXT NOT NULL DEFAULT '',UNIQUE(plan_id,occurrence));
CREATE TABLE task_handovers(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES inspection_tasks(id),from_user TEXT NOT NULL,to_user TEXT NOT NULL REFERENCES users(id),reason TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE product_evidence(id TEXT PRIMARY KEY,record_id TEXT NOT NULL REFERENCES inspection_records(id),point_id TEXT REFERENCES measurement_points(id),kind TEXT NOT NULL,title TEXT NOT NULL,path TEXT NOT NULL DEFAULT '',sha256 TEXT NOT NULL DEFAULT '',content TEXT NOT NULL DEFAULT '',metadata TEXT NOT NULL DEFAULT '{}',created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,deleted_at TEXT NOT NULL DEFAULT '');
CREATE INDEX evidence_record ON product_evidence(record_id,created_at);
CREATE TABLE report_versions(id TEXT PRIMARY KEY,record_id TEXT NOT NULL REFERENCES inspection_records(id),revision INTEGER NOT NULL,snapshot TEXT NOT NULL,sha256 TEXT NOT NULL,confirmed_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,reason TEXT NOT NULL DEFAULT '',UNIQUE(record_id,revision));
CREATE TRIGGER immutable_report_update BEFORE UPDATE ON report_versions BEGIN SELECT RAISE(ABORT,'正式报告版本不可修改'); END;
CREATE TRIGGER immutable_report_delete BEFORE DELETE ON report_versions BEGIN SELECT RAISE(ABORT,'正式报告版本不可删除'); END;
CREATE TABLE recycle_items(id TEXT PRIMARY KEY,entity TEXT NOT NULL,entity_id TEXT NOT NULL,group_id TEXT NOT NULL,actor_id TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,restored_at TEXT NOT NULL DEFAULT '');
CREATE UNIQUE INDEX live_recycle_item ON recycle_items(entity,entity_id) WHERE restored_at='';
CREATE TABLE chat_conversations(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),mode TEXT NOT NULL,title TEXT NOT NULL,model TEXT NOT NULL,messages TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX chat_owner ON chat_conversations(user_id,mode,updated_at);
ALTER TABLE defects ADD COLUMN check_item_key TEXT NOT NULL DEFAULT '';
CREATE UNIQUE INDEX defect_check_item ON defects(record_id,check_item_key) WHERE check_item_key<>'';
ALTER TABLE audit_logs ADD COLUMN actor_id TEXT NOT NULL DEFAULT '';
ALTER TABLE audit_logs ADD COLUMN actor_name TEXT NOT NULL DEFAULT '';
CREATE TABLE product_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT INTO product_settings VALUES('retention_days','90');
UPDATE schema_meta SET version=7;
